def build_counting_plan(width):
    if isinstance(width, bool) or not isinstance(width, int):
        raise TypeError("width must be an integer")
    if width <= 0:
        raise ValueError("width must be positive")

    layer1 = tuple(
        ("prepare", register, index)
        for register in ("control", "work")
        for index in range(width)
    )
    targets = tuple(range(width))
    layer2 = tuple(
        ("controlled_cycle", index, 2 ** (index + 1), targets)
        for index in range(width)
    )
    layer3 = tuple(
        ("swap", "control", low, width - 1 - low)
        for low in range(width // 2)
    )

    layer4_items = []
    for target in range(width):
        layer4_items.append(("mix", target))
        for source in range(target + 1, width):
            layer4_items.append(
                ("phase", source, target, 2 ** (source - target + 1))
            )
    layer4 = tuple(layer4_items)
    layer5 = tuple(
        ("measure", "control", index, index)
        for index in range(width)
    )
    return layer1, layer2, layer3, layer4, layer5

